 pub fn terminal_is_empty(&self)->bool{self.backing.terminal_is_empty()&&self.receiver.terminal_is_empty()&&self.retired_header.is_none()&&self.output.is_none()&&self.retirement.is_empty()&&self.action.terminal_is_empty()&&!self.checkpoint_unresolved&&self.authority.is_none()&&self.binding.is_none()}
