impl<I:NativeValueSource+?Sized,T:NativeReceive<I>> Drop for NativeReceiveSlot<I,T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native child receiving requires funded closure");}}
